import{_ as t,a0 as o,w as r,s as d,I as n,x as a,a1 as i,A as p,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const M=JSON.parse('{"title":"使用 Linux MLVWM 打造复古苹果桌面 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux MLVWM 打造复古苹果桌面 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux MLVWM 打造复古苹果桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux MLVWM 打造复古苹果桌面 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191217 Build a retro Apple desktop with the Linux MLVWM","title":"使用 Linux MLVWM 打造复古苹果桌面","tag":"201912","desc":""},"relativePath":"201912/20191217 Build a retro Apple desktop with the Linux MLVWM.md","filePath":"[post].md"}'),u={name:"201912/20191217 Build a retro Apple desktop with the Linux MLVWM.md"};function c(m,s,h,g,k,b){const e=o("Link");return r(),d("div",null,[s[34]||(s[34]=n("h1",{id:"使用-linux-mlvwm-打造复古苹果桌面",tabindex:"-1"},[a("使用 Linux MLVWM 打造复古苹果桌面 "),n("a",{class:"header-anchor",href:"#使用-linux-mlvwm-打造复古苹果桌面","aria-label":"Permalink to “使用 Linux MLVWM 打造复古苹果桌面”"},"​")],-1)),s[35]||(s[35]=n("blockquote",null,[n("p",null,"本文是 24 天 Linux 桌面特别系列的一部分。如果老式的苹果电脑是用开源 POSIX 构建的呢？你可以通过构建 Macintosh 式的虚拟窗口管理器来实现。")],-1)),s[36]||(s[36]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/1980s-computer-yearbook.png?itok=eGOYEKK-",alt:"Person typing on a 1980's computer",title:"Person typing on a 1980's computer"})],-1)),n("p",null,[s[2]||(s[2]=a("想象一下穿越到另一段平行历史，Apple II GS 和 MacOS 7 是基于开源 ",-1)),i(e,{href:"https://opensource.com/article/19/7/what-posix-richard-stallman-explains"},{default:p(()=>[...s[0]||(s[0]=[a("POSIX",-1)])]),_:1}),s[3]||(s[3]=a(" 构建的，它使用了与现代 Linux 相同的所有惯例，例如纯文本配置文件和模块化系统设计。这样的操作系统将为其用户带来什么？你可以使用 ",-1)),i(e,{href:"http://www2u.biglobe.ne.jp/~y-miyata/mlvwm.html"},{default:p(()=>[...s[1]||(s[1]=[a("Macintosh 式的虚拟窗口管理器（MLVWM）",-1)])]),_:1}),s[4]||(s[4]=a("来回答这些问题（甚至更多！）。",-1))]),s[37]||(s[37]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/uploads/advent-mlvwm-file.jpg",alt:"MLVWM running on Slackware 14.2",title:"MLVWM running on Slackware 14.2"})],-1)),s[38]||(s[38]=n("h3",{id:"安装-mlvwm",tabindex:"-1"},[a("安装 MLVWM "),n("a",{class:"header-anchor",href:"#安装-mlvwm","aria-label":"Permalink to “安装 MLVWM”"},"​")],-1)),s[39]||(s[39]=n("p",null,"MLVWM 安装并不容易，并且可能不在你的发行版软件仓库中。如果你有时间理解翻译不佳的 README 文件，编辑一些配置文件，收集并调整一些旧的 .xpm 图片，编辑一两个 Xorg 选项，那么你就可以体验 MLVWM。不管怎么说，这是一个新奇的窗口管理器，其最新版本可以追溯到 2000 年。",-1)),n("p",null,[s[6]||(s[6]=a("要编译 MLVWM，你必须安装 imake，它提供了 ",-1)),s[7]||(s[7]=n("code",null,"xmkmf",-1)),s[8]||(s[8]=a(" 命令。你可以从发行版的软件仓库中安装 imake，也可以直接从 ",-1)),i(e,{href:"http://cgit.freedesktop.org/xorg/util/imake"},{default:p(()=>[...s[5]||(s[5]=[a("Freedesktop.org",-1)])]),_:1}),s[9]||(s[9]=a(" 获得。假设你已经有 ",-1)),s[10]||(s[10]=n("code",null,"xmkmf",-1)),s[11]||(s[11]=a(" 命令，请进入包含 MLVWM 源码的目录，然后运行以下命令进行构建：",-1))]),s[40]||(s[40]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ xmkmf -a</span></span>
<span class="line"><span>$ make</span></span></code></pre></div>`,1)),n("p",null,[s[13]||(s[13]=a("构建后，编译后的 ",-1)),s[14]||(s[14]=n("code",null,"mlvwm",-1)),s[15]||(s[15]=a(" 二进制文件位于 ",-1)),s[16]||(s[16]=n("code",null,"mlvwm",-1)),s[17]||(s[17]=a(" 目录中。将其移动到",-1)),i(e,{href:"https://opensource.com/article/17/6/set-path-linux"},{default:p(()=>[...s[12]||(s[12]=[a("你的 PATH",-1)])]),_:1}),s[18]||(s[18]=a(" 的任何位置：",-1))]),s[41]||(s[41]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mv mlvwm/mlvwm /usr/local/bin/</span></span></code></pre></div><h4 id="编辑配置文件" tabindex="-1">编辑配置文件 <a class="header-anchor" href="#编辑配置文件" aria-label="Permalink to “编辑配置文件”">​</a></h4><p>现在已经安装好 MLVWM，但是如果不调整几个配置文件并仔细放好所需的图像文件，它将无法正确启动。示例配置文件位于你下载的源代码的 <code>sample_rc</code> 目录中。将文件 <code>Mlvwm-Netscape</code> 和 <code>Mlvwm-Xterm</code> 复制到你的主目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp sample_rc/Mlvwm-{Netscape,Xterm} $HOME</span></span></code></pre></div><p>将 <code>Mlvwmrc</code> 改名为 <code>$HOME/.mlvwmrc</code>（是的，即使示例文件的名称看似是大写字母，但你也必须使用小写的 “m”）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp sample_rc/Mlvwmrc $HOME/.mlvwmrc</span></span></code></pre></div><p>打开 <code>.mlwmrc</code> 并找到第 54-55 行，它们定义了 MLVWM 在菜单和 UI 中使用的像素图的路径（<code>IconPath</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Set icon search path. It needs before &quot;Style&quot;.</span></span>
<span class="line"><span>IconPath /usr/local/include/X11/pixmaps:/home2/tak/bin/pixmap</span></span></code></pre></div><p>调整路径以匹配你填充图像的路径（我建议使用 <code>$HOME/.local/share/pixmaps</code>）。MLVWM 不提供像素图，因此需要你提供构建桌面所需图标。</p><p>即使你有位于系统其他位置的像素图（例如 <code>/usr/share/pixmaps</code>），也要这样做，因为你需要调整像素图的大小，你可能也不想在系统范围内执行此操作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Set icon search path. It needs before &quot;Style&quot;.</span></span>
<span class="line"><span>IconPath /home/seth/.local/share/pixmaps</span></span></code></pre></div><h4 id="选择像素图" tabindex="-1">选择像素图 <a class="header-anchor" href="#选择像素图" aria-label="Permalink to “选择像素图”">​</a></h4><p>你已将 <code>.local/share/pixmaps</code> 目录定义为像素图源路径，但是该目录和图像均不存在。创建目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir -p $HOME/.local/share/pixmaps</span></span></code></pre></div><p>现在，配置文件将图像分配给菜单项和 UI 元素，但是系统中不存在这些图像。要解决此问题，请通读配置文件并找到每个 .xpm 图像。对于配置中列出的每个图像，将具有相同文件名的图像（或更改配置文件中的文件名）添加到你的 IconPath 目录。</p><p><code>.mlvwmrc</code> 文件的注释很好，因此你可以大致了解要编辑的内容。无论如何，这只是第一步。你可以随时回来更改桌面外观。</p><p>这有些例子。</p><p>此代码块设置屏幕左上角的图标：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Register the menu</span></span>
<span class="line"><span>Menu Apple, Icon label1.xpm, Stick</span></span></code></pre></div><p><code>label1.xpm</code> 图像实际上在源代码的 <code>pixmap</code> 目录中，但我更喜欢使用来自 <code>/usr/share/pixmaps</code> 的 <code>Penguin.xpm</code>（在 Slackware 上）。无论使用什么，都必须将自定义像素图放在 <code>~/.local/share/pixmaps</code> 中，并在配置中更改像素图的名称，或者重命名像素图以匹配配置文件中当前的名称。</p><p>此代码块定义了左侧菜单中列出的应用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;About this Workstation...&quot; NonSelect, Gray, Action About</span></span>
<span class="line"><span>&quot;&quot; NonSelect</span></span>
<span class="line"><span>&quot;Terminal&quot;      Icon mini-display.xpm, Action Exec &quot;kterm&quot; exec kterm -ls</span></span>
<span class="line"><span>&quot;Editor&quot;  Action Exec &quot;mule&quot; exec mule, Icon mini-edit.xpm</span></span>
<span class="line"><span>&quot;calculator&quot; Action Exec &quot;xcal&quot; exec xcalc, Icon mini-calc.xpm</span></span>
<span class="line"><span>END</span></span></code></pre></div><p>通过遵循与配置文件中相同的语法，你可以自定义像素图并将自己的应用添加到菜单中（例如，我将 <code>mule</code> 更改为 <code>emacs</code>）。这是你在 MLVWM GUI 中打开应用的入口，因此请列出你要快速访问的所有内容。你可能还希望包括指向 <code>/usr/share/applications</code> 文件夹的快捷方式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;Applications&quot; Icon Penguin.xpm, Action Exec &quot;thunar /usr/share/applications&quot; exec thunar /usr/share/applications</span></span></code></pre></div><p>完成编辑配置文件并将自己的图像添加到 IconPath 目录后，必须将所有像素图的大小都调整为大约 16x16 像素。（MLVWM 的默认设置不一致，因此存在变化空间。）你可以使用 ImageMagick 进行批量操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for i in ~/.local/share/mlvwm-pixmaps/*xpm ; do convert -resize &#39;16x16^&#39; $i; done</span></span></code></pre></div><h3 id="启动-mlvwm" tabindex="-1">启动 MLVWM <a class="header-anchor" href="#启动-mlvwm" aria-label="Permalink to “启动 MLVWM”">​</a></h3><p>最简单的运行 MLVWM 的方式是让 Xorg 完成大部分工作。首先，你必须创建一个 <code>$HOME/.xinitrc</code> 文件。我从 Slackware 复制了这个，它也是从 Xorg 拿来的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span># $XConsortium: xinitrc.cpp,v 1.4 91/08/22 11:41:34 rws Exp $</span></span>
<span class="line"><span></span></span>
<span class="line"><span>userresources=$HOME/.Xresources</span></span>
<span class="line"><span>usermodmap=$HOME/.Xmodmap</span></span>
<span class="line"><span>sysresources=/etc/X11/xinit/.Xresources</span></span>
<span class="line"><span>sysmodmap=/etc/X11/xinit/.Xmodmap</span></span>
<span class="line"><span></span></span>
<span class="line"><span># merge in defaults and keymaps</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ -f $sysresources ]; then</span></span>
<span class="line"><span>    xrdb -merge $sysresources</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ -f $sysmodmap ]; then</span></span>
<span class="line"><span>    xmodmap $sysmodmap</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ -f $userresources ]; then</span></span>
<span class="line"><span>    xrdb -merge $userresources</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ -f $usermodmap ]; then</span></span>
<span class="line"><span>    xmodmap $usermodmap</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Start the window manager:</span></span>
<span class="line"><span>if [ -z &quot;$DESKTOP_SESSION&quot; -a -x /usr/bin/ck-launch-session ]; then</span></span>
<span class="line"><span>  exec ck-launch-session /usr/local/bin/mlvwm</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>  exec /usr/local/bin/mlvwm</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>根据此文件，<code>startx</code> 命令的默认操作是启动 MLVWM。但是，你的发行版可能对于图形服务器启动（或被终止以重新启动）时会发生的情况有其他做法，因此此文件可能对你没有什么帮助。在许多发行版上，你可以添加 .desktop 文件到 <code>/usr/share/xsessions</code> 中，以将其列在 GDM 或 KDM 菜单中，因此创建名为 <code>mlvwm.desktop</code> 的文件并输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Desktop Entry]</span></span>
<span class="line"><span>Name=Mlvwm</span></span>
<span class="line"><span>Comment=Macintosh-like virtual window manager</span></span>
<span class="line"><span>Exec=/usr/local/bin/mlvwm</span></span>
<span class="line"><span>TryExec=ck-launch-session /usr/local/bin/mlvwm</span></span>
<span class="line"><span>Type=Application</span></span></code></pre></div><p>从桌面会话注销并重新登录到 MLVWM。默认情况下，会话管理器（KDM、GDM 或 LightDM，具体取决于你的设置）将继续登录到以前的桌面，因此在登录之前必须覆盖它。</p><p>对于 GDM：</p><p><img src="https://opensource.com/sites/default/files/advent-gdm_2.jpg" alt=""></p><p>对于 SDDM：</p><p><img src="https://opensource.com/sites/default/files/advent-kdm_1.jpg" alt=""></p><h4 id="强制启动" tabindex="-1">强制启动 <a class="header-anchor" href="#强制启动" aria-label="Permalink to “强制启动”">​</a></h4><p>如果 MLVWM 无法启动，请尝试安装 XDM，这是一个轻量级会话管理器，它不会查询 <code>/usr/share/xsessions</code> 的内容，而是执行经过身份验证用户的所有 <code>.xinitrc</code> 操作。</p><p><img src="https://opensource.com/sites/default/files/uploads/advent-mlvwm-chess.jpg" alt="MLVWM" title="MLVWM"></p><h3 id="打造自己的复古苹果" tabindex="-1">打造自己的复古苹果 <a class="header-anchor" href="#打造自己的复古苹果" aria-label="Permalink to “打造自己的复古苹果”">​</a></h3><p>MLVWM 桌面未经打磨、不完美、模仿到位且充满乐趣。你看到的许多菜单项都是未实现的，但你可以使它们变得活跃且有意义。</p><p>这是一次让你时光倒流、改变历史，让老式苹果系列电脑成为开源堡垒的机会。成为一名修正主义者，设计你自己的复古苹果桌面，最重要的是，它有乐趣。</p><hr>`,43)),n("p",null,[s[20]||(s[20]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/19/12/linux-mlvwm-desktop"},{default:p(()=>[...s[19]||(s[19]=[a("https://opensource.com/article/19/12/linux-mlvwm-desktop",-1)])]),_:1})]),n("p",null,[s[25]||(s[25]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[21]||(s[21]=[a("Seth Kenlon",-1)])]),_:1}),s[26]||(s[26]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[22]||(s[22]=[a("lujun9972",-1)])]),_:1}),s[27]||(s[27]=a(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:p(()=>[...s[23]||(s[23]=[a("geekpi",-1)])]),_:1}),s[28]||(s[28]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[24]||(s[24]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[31]||(s[31]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[29]||(s[29]=[a("LCTT",-1)])]),_:1}),s[32]||(s[32]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[30]||(s[30]=[a("Linux中国",-1)])]),_:1}),s[33]||(s[33]=a(" 荣誉推出",-1))])])}const v=t(u,[["render",c]]);export{M as __pageData,v as default};
